using Inlay.Platform.Native;

namespace Inlay.Platform.Images;

/// <summary>A thumbnail as premultiplied BGRA pixels, top-down rows: ready for a SoftwareBitmap/WriteableBitmap.</summary>
internal sealed record ThumbnailPixels(int Width, int Height, byte[] Bgra);

/// <summary>
/// Thumbnails from the Windows thumbnail cache (<c>IShellItemImageFactory::GetImage</c>): the same small images
/// Explorer shows, generated by the system's thumbnail providers from embedded or downscaled data. Inlay itself never
/// decodes a full image for a thumbnail. Requests run on one background STA thread, started on the first request and
/// gone after a short idle, and results are kept in a bounded LRU.
/// <para>
/// Cloud-only placeholders: the first attempt for every file is <c>SIIGBF_INCACHEONLY</c> (the cache, nothing is
/// read); only files whose content is on this PC go on to <c>SIIGBF_THUMBNAILONLY</c>, which may read the file to
/// build the thumbnail. A placeholder without a cached thumbnail gets none (null: show the generic tile), so a
/// thumbnail never downloads a file.
/// </para>
/// </summary>
internal sealed unsafe class Thumbnails : IDisposable
{
    public const int DefaultCapacity = 200;

    private static readonly Guid IidShellItemImageFactory = new("bcc18b79-ba16-442f-80c4-8a59c30c463b");
    private const int SlotGetImage = 3;
    private const int SIIGBF_THUMBNAILONLY = 0x08;
    private const int SIIGBF_INCACHEONLY = 0x10;
    private const int IdleExitMs = 30_000;
    private const int MinSize = 16;
    private const int MaxSize = 1024;

    private readonly int _capacity;
    private readonly object _gate = new(); // Monitor.Wait/Pulse: the worker sleeps on it
    private readonly Dictionary<Key, LinkedListNode<(Key Key, ThumbnailPixels Pixels)>> _cache = [];
    private readonly LinkedList<(Key Key, ThumbnailPixels Pixels)> _lru = new();
    private readonly Dictionary<Key, TaskCompletionSource<ThumbnailPixels?>> _inFlight = [];
    private readonly Queue<Key> _queue = new();
    private Thread? _thread;
    private bool _disposed;

    public Thumbnails(int capacity = DefaultCapacity) => _capacity = Math.Max(1, capacity);

    /// <param name="Version">The file's last-write time (default for library files, which never change): a changed file gets a new thumbnail.</param>
    private readonly record struct Key(string Path, int Size, DateTime Version);

    public int Count
    {
        get
        {
            lock (_gate)
                return _cache.Count;
        }
    }

    /// <summary>A cached thumbnail, or null (no disk access: safe on any thread).</summary>
    public ThumbnailPixels? TryGetCached(string path, int sizePx, DateTime version = default)
    {
        lock (_gate)
        {
            if (!_cache.TryGetValue(new(path, Math.Clamp(sizePx, MinSize, MaxSize), version), out var node))
                return null;
            _lru.Remove(node);
            _lru.AddFirst(node);
            return node.Value.Pixels;
        }
    }

    /// <summary>
    /// The thumbnail of <paramref name="path"/> fitting <paramref name="sizePx"/> × <paramref name="sizePx"/> physical
    /// pixels (aspect ratio kept), or null when there is none. Completes on a pool thread.
    /// </summary>
    public Task<ThumbnailPixels?> GetAsync(string path, int sizePx, DateTime version = default)
    {
        if (TryGetCached(path, sizePx, version) is { } cached)
            return Task.FromResult<ThumbnailPixels?>(cached);
        var key = new Key(path, Math.Clamp(sizePx, MinSize, MaxSize), version);
        lock (_gate)
        {
            if (_disposed)
                return Task.FromResult<ThumbnailPixels?>(null);
            if (_inFlight.TryGetValue(key, out var running))
                return running.Task;
            var tcs = new TaskCompletionSource<ThumbnailPixels?>(TaskCreationOptions.RunContinuationsAsynchronously);
            _inFlight[key] = tcs;
            _queue.Enqueue(key);
            if (_thread is null)
            {
                _thread = new Thread(Run) { IsBackground = true, Name = "Inlay thumbnails", Priority = ThreadPriority.BelowNormal };
                _thread.SetApartmentState(ApartmentState.STA);
                _thread.Start();
            }
            else
            {
                Monitor.PulseAll(_gate);
            }

            return tcs.Task;
        }
    }

    /// <summary>Drops every cached thumbnail (the feature was turned off).</summary>
    public void Clear()
    {
        lock (_gate)
        {
            _cache.Clear();
            _lru.Clear();
        }
    }

    private void Run()
    {
        while (true)
        {
            Key key;
            lock (_gate)
            {
                while (_queue.Count == 0)
                {
                    if (_disposed || !Monitor.Wait(_gate, IdleExitMs) && _queue.Count == 0)
                    {
                        _thread = null;
                        return;
                    }
                }

                key = _queue.Dequeue();
            }

            ThumbnailPixels? pixels = null;
            try
            {
                pixels = Extract(key.Path, key.Size);
            }
            catch (Exception ex)
            {
                Log.Error("thumbnail", ex);
            }

            TaskCompletionSource<ThumbnailPixels?>? tcs;
            lock (_gate)
            {
                _inFlight.Remove(key, out tcs);
                if (pixels is not null && !_disposed)
                    Store(key, pixels);
            }

            tcs?.TrySetResult(pixels);
        }
    }

    private void Store(Key key, ThumbnailPixels pixels)
    {
        if (_cache.Remove(key, out var old))
            _lru.Remove(old);
        _cache[key] = _lru.AddFirst((key, pixels));
        while (_cache.Count > _capacity && _lru.Last is { } last)
        {
            _lru.RemoveLast();
            _cache.Remove(last.Value.Key);
        }
    }

    private static ThumbnailPixels? Extract(string path, int size)
    {
        FileAttributes attributes;
        try
        {
            attributes = File.GetAttributes(path);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            return null;
        }

        if (ImageApi.SHCreateItemFromParsingName(path, 0, IidShellItemImageFactory, out var factory) < 0 || factory == 0)
            return null;
        try
        {
            var bitmap = GetImage(factory, size, SIIGBF_THUMBNAILONLY | SIIGBF_INCACHEONLY);
            if (bitmap == 0 && !FolderCache.IsCloudOnly(attributes))
                bitmap = GetImage(factory, size, SIIGBF_THUMBNAILONLY);
            if (bitmap == 0)
                return null;
            try
            {
                return ToPixels(bitmap);
            }
            finally
            {
                Gdi32.DeleteObject(bitmap);
            }
        }
        finally
        {
            ImageCodec.Release(factory);
        }
    }

    private static nint GetImage(nint factory, int size, int flags)
    {
        nint bitmap = 0;
        var box = new SIZE { cx = size, cy = size };
        var hr = ((delegate* unmanaged[Stdcall]<nint, SIZE, int, nint*, int>)(*(nint**)factory)[SlotGetImage])(factory, box, flags, &bitmap);
        return hr >= 0 ? bitmap : 0;
    }

    /// <summary>The bitmap as top-down BGRA. Thumbnails without transparency come with alpha 0 throughout: made opaque.</summary>
    private static ThumbnailPixels? ToPixels(nint bitmap)
    {
        var dc = IconApi.GetDC(0);
        try
        {
            var header = new BITMAPINFOHEADER { biSize = sizeof(BITMAPINFOHEADER) };
            if (Gdi32.GetDIBits(dc, bitmap, 0, 0, null, &header, Gdi32.DIB_RGB_COLORS) == 0)
                return null;
            var width = header.biWidth;
            var height = Math.Abs(header.biHeight);
            if (width <= 0 || height <= 0 || width > 4096 || height > 4096)
                return null;
            header = new BITMAPINFOHEADER { biSize = sizeof(BITMAPINFOHEADER), biWidth = width, biHeight = -height, biPlanes = 1, biBitCount = 32 };
            var pixels = new byte[width * height * 4];
            fixed (byte* p = pixels)
            {
                if (Gdi32.GetDIBits(dc, bitmap, 0, (uint)height, p, &header, Gdi32.DIB_RGB_COLORS) == 0)
                    return null;
            }

            var hasAlpha = false;
            for (var i = 3; i < pixels.Length && !hasAlpha; i += 4)
                hasAlpha = pixels[i] != 0;
            if (!hasAlpha)
            {
                for (var i = 3; i < pixels.Length; i += 4)
                    pixels[i] = 255;
            }

            return new ThumbnailPixels(width, height, pixels);
        }
        finally
        {
            _ = IconApi.ReleaseDC(0, dc);
        }
    }

    public void Dispose()
    {
        List<TaskCompletionSource<ThumbnailPixels?>> waiting;
        lock (_gate)
        {
            _disposed = true;
            _queue.Clear();
            waiting = [.. _inFlight.Values];
            _inFlight.Clear();
            _cache.Clear();
            _lru.Clear();
            Monitor.PulseAll(_gate);
        }

        foreach (var t in waiting)
            t.TrySetResult(null);
    }
}
